import os,json,subprocess
from pathlib import Path
root=Path("/srv/projects/pink-iptv")
gateway=root/"vpn/gateway"
unit=Path("/etc/systemd/system/pink-vpn.service")
old=("/etc/pink-vpn","/var/lib/pink-vpn")
new=(str(gateway),str(root/"vpn/data"))
out={"paths":{},"files":{},"unit":{},"services":{}}
for p in (gateway,root/"vpn/data",unit):
 out["paths"][str(p)]={"real_dir":p.is_dir() and not p.is_symlink(),"real_file":p.is_file() and not p.is_symlink()}
for p in gateway.glob("*.py"):
 b=p.read_bytes()
 out["files"][p.name]={"old_refs":{s:b.count(s.encode()) for s in old},"new_refs":{s:b.count(s.encode()) for s in new},"syntax_ok":subprocess.run(["python3","-c","import ast,sys;ast.parse(open(sys.argv[1]).read())",str(p)],capture_output=True,timeout=10).returncode==0,"uses_relative_paths":any(w in b for w in (b"__file__",b"Path(__file__)",b"os.path.dirname(__file__)"))}
if unit.is_file():
 b=unit.read_text()
 out["unit"]["old_refs"]={s:b.count(s) for s in old}
 out["unit"]["new_refs"]={s:b.count(s) for s in new}
 out["unit"]["safe_directives"]=[line for line in b.splitlines() if line.startswith(("ExecStart=","WorkingDirectory=","User=","Group=","Type=","EnvironmentFile="))]
 out["unit"]["syntax_ok"]=subprocess.run(["systemd-analyze","verify",str(unit)],capture_output=True,timeout=12).returncode==0
for n in ("pink-vpn","pink-iptv-backend","nginx","ssh","pm2-iptvpn-bot","pm2-root"):
 out["services"][n]=subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip()
print(json.dumps(out,sort_keys=True))
